style:
.tw-cosolar--jianlan.resume-paper {
  color: #23272f;
}

.tw-cosolar--jianlan.resume-paper .paper-header {
  margin: 0 0 4mm;
  padding: 0 0 3.2mm;
  border: none;
}

.tw-cosolar--jianlan.resume-paper .paper-header--photo {
  align-items: flex-start;
  gap: 7mm;
}

.tw-cosolar--jianlan.resume-paper .paper-photo {
  order: -1;
  width: 25mm;
  height: 32mm;
  border: none;
  border-radius: 1.6mm;
  box-shadow: none;
}

.tw-cosolar--jianlan.resume-paper .paper-photo--monogram {
  order: -1;
  display: grid;
  place-items: center;
  width: 25mm;
  height: 32mm;
  border-radius: 1.6mm;
  background: #e8f0fb;
  color: #2e6fd1;
  font-size: calc(var(--paper-base-size) * 1.8);
  font-weight: 600;
}

.tw-cosolar--jianlan.resume-paper .paper-header__main {
  display: block;
  flex: 1 1 auto;
  min-width: 0;
}

.tw-cosolar--jianlan.resume-paper .paper-name {
  color: #1c2028;
  font-size: calc(var(--paper-base-size) * 2.25);
  letter-spacing: 0.1em;
}

.tw-cosolar--jianlan.resume-paper .paper-role {
  margin-top: 2mm;
  color: #2b3038;
  font-weight: 600;
}

.tw-cosolar--jianlan.resume-paper .paper-role::before {
  content: "求职意向：";
  color: #7a828e;
  font-weight: 400;
}

.tw-cosolar--jianlan.resume-paper .paper-contacts--labeled {
  display: flex;
  flex-wrap: wrap;
  gap: 1.6mm 7mm;
  margin-top: 4.5mm;
  align-items: baseline;
  color: #2b3038;
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-cosolar--jianlan.resume-paper .paper-contacts::before {
  content: "MY RESUME";
  margin-right: 2mm;
  color: #2e6fd1;
  font-weight: 700;
  font-size: calc(var(--paper-base-size) * 1.02);
  letter-spacing: 0.06em;
}

.tw-cosolar--jianlan.resume-paper .paper-contact {
  display: inline-flex;
  gap: 1.2mm;
  min-width: 0;
}

.tw-cosolar--jianlan.resume-paper .paper-contact__label {
  color: #2e6fd1;
  font-weight: 600;
}

.tw-cosolar--jianlan.resume-paper .paper-header::after {
  content: "";
  display: block;
  height: 1.7mm;
  margin-top: 3mm;
  border-radius: 999px;
  background: linear-gradient(90deg, #3f8ae0 0%, #1d55a4 55%, #123a6b 100%);
  print-color-adjust: exact;
}

.tw-cosolar--jianlan.resume-paper .paper-section {
  margin-bottom: 4.2mm;
}

.tw-cosolar--jianlan.resume-paper .paper-style-line .paper-section__title {
  display: block;
  margin: 0 0 2.4mm;
  color: #1f2430;
  font-size: calc(var(--paper-base-size) * 1.14);
  font-weight: 700;
  letter-spacing: 0.05em;
}

.tw-cosolar--jianlan.resume-paper .paper-style-line .paper-section__title span::before {
  display: none;
}

.tw-cosolar--jianlan.resume-paper .paper-section .paper-section__title::after {
  content: none;
}

.tw-cosolar--jianlan.resume-paper .paper-section .paper-section__icon {
  display: none;
}

.tw-cosolar--jianlan.resume-paper .paper-item-head {
  display: block;
}

.tw-cosolar--jianlan.resume-paper .paper-item-title {
  float: left;
  width: 31%;
  color: #1f2430;
  font-size: calc(var(--paper-base-size) * 1.02);
}

.tw-cosolar--jianlan.resume-paper .paper-item-period {
  float: right;
  width: 26%;
  color: #7a828e;
  font-size: calc(var(--paper-base-size) * 0.86);
  text-align: right;
}

.tw-cosolar--jianlan.resume-paper .paper-item-sub {
  display: block;
  margin-top: 0;
  color: #3a3f4a;
  font-size: calc(var(--paper-base-size) * 0.94);
  text-align: center;
}

.tw-cosolar--jianlan.resume-paper .paper-item-sub span {
  white-space: nowrap;
}

.tw-cosolar--jianlan.resume-paper .paper-item-sub span + span::before {
  content: none;
}

.tw-cosolar--jianlan.resume-paper .paper-item-sub span:not(:last-child)::after {
  content: "|";
  margin: 0 2.6mm;
  color: #c3c9d1;
}

.tw-cosolar--jianlan.resume-paper .paper-item > .paper-rich,
.tw-cosolar--jianlan.resume-paper .paper-item > .paper-note,
.tw-cosolar--jianlan.resume-paper .paper-item > .paper-meta-line,
.tw-cosolar--jianlan.resume-paper .paper-item > .paper-facts,
.tw-cosolar--jianlan.resume-paper .paper-item > .paper-plain {
  clear: both;
}

.tw-cosolar--jianlan.resume-paper .paper-item::after {
  content: "";
  display: block;
  clear: both;
}

.tw-cosolar--jianlan.resume-paper .paper-rich {
  margin-top: 0.8mm;
  color: #33383f;
}

.tw-cosolar--jianlan.resume-paper .is-education .paper-rich ul,
.tw-cosolar--jianlan.resume-paper .is-work_experience .paper-rich ul,
.tw-cosolar--jianlan.resume-paper .is-project_experience .paper-rich ul,
.tw-cosolar--jianlan.resume-paper .is-campus_experience .paper-rich ul {
  margin: 0;
  padding-left: 0;
  list-style: none;
}

.tw-cosolar--jianlan.resume-paper .is-work_experience .paper-rich::before {
  content: "工作内容：";
  display: block;
  color: #3a3f4a;
}

.tw-cosolar--jianlan.resume-paper .is-award .paper-section__body {
  column-count: 2;
  column-gap: 9mm;
  column-rule: 1px solid #e6eaf0;
}

.tw-cosolar--jianlan.resume-paper .is-award .paper-item {
  break-inside: avoid;
}

.tw-cosolar--jianlan.resume-paper .is-award .paper-item-title {
  width: 64%;
}

.tw-cosolar--jianlan.resume-paper .is-award .paper-item-period {
  width: 34%;
}

.tw-cosolar--jianlan.resume-paper .is-award .paper-item-sub {
  clear: both;
  text-align: left;
}

.tw-cosolar--jianlan.resume-paper .is-award .paper-item-title::before {
  content: "•";
  margin-right: 1.8mm;
  color: #2e6fd1;
}

.tw-cosolar--jianlan.resume-paper .paper-skill {
  border-bottom: none;
}

.tw-cosolar--jianlan.resume-paper .paper-skill__name {
  color: #1f2430;
  font-weight: 600;
}

.tw-cosolar--jianlan.resume-paper .paper-skill__dots {
  display: none;
}

.tw-cosolar--jianlan.resume-paper .paper-skill__level {
  display: inline;
  color: #5c646e;
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-cosolar--jianlan.resume-paper .paper-note__tag {
  color: #2e6fd1;
}

.tw-cosolar--jianlan.resume-paper .paper-footer {
  border-top-color: #e6eaf0;
  color: #8a93a0;
}

.tw-cosolar--jianlan.resume-paper .is-job_intention .paper-item {
  display: flex;
  flex-wrap: wrap;
  gap: 1.2mm 8mm;
}

.tw-cosolar--jianlan.resume-paper .is-job_intention .paper-item-head {
  display: flex;
  flex: 0 0 auto;
  gap: 8mm;
  justify-content: flex-start;
}

.tw-cosolar--jianlan.resume-paper .is-job_intention .paper-item-title::before {
  content: "意向岗位：";
  color: #7a828e;
  font-weight: 400;
}

.tw-cosolar--jianlan.resume-paper .is-job_intention .paper-item-period::before {
  content: "意向城市：";
  color: #7a828e;
  font-weight: 400;
}

.tw-cosolar--jianlan.resume-paper .is-job_intention .paper-item-sub {
  flex: 0 0 auto;
  display: flex;
  flex-wrap: wrap;
  gap: 1.2mm 8mm;
  margin-top: 0;
  color: #2b3038;
}

.tw-cosolar--jianlan.resume-paper .is-job_intention .paper-item-sub span + span::before {
  content: "·";
  margin-right: 6mm;
  color: #c3c9d1;
}

/* 显式选择的列表样式接管模板默认圆点装饰，避免 data-list 被模板 ul/li 规则盖掉。 */
.tw-cosolar--jianlan.resume-paper .paper-rich ul[data-list],
.tw-cosolar--jianlan.resume-paper .paper-rich ol[data-list] {
  margin: 0.5mm 0 0;
  padding-left: 1.2em;
}
.tw-cosolar--jianlan.resume-paper .paper-rich ul[data-list] > li,
.tw-cosolar--jianlan.resume-paper .paper-rich ol[data-list] > li {
  padding-left: 0;
  position: relative;
}
.tw-cosolar--jianlan.resume-paper .paper-rich ul[data-list] > li::before,
.tw-cosolar--jianlan.resume-paper .paper-rich ol[data-list] > li::before {
  content: none;
  width: auto;
  height: auto;
  border-radius: 0;
  background: none;
  border: 0;
  box-shadow: none;
  left: auto;
  right: auto;
  top: auto;
  margin: 0;
  padding: 0;
}
.tw-cosolar--jianlan.resume-paper .paper-rich ul[data-list="disc"] { list-style-type: disc; }
.tw-cosolar--jianlan.resume-paper .paper-rich ul[data-list="circle"] { list-style-type: circle; }
.tw-cosolar--jianlan.resume-paper .paper-rich ul[data-list="square"] { list-style-type: square; }
.tw-cosolar--jianlan.resume-paper .paper-rich ul[data-list="square-open"] { list-style-type: "□   "; }
.tw-cosolar--jianlan.resume-paper .paper-rich ul[data-list="square-open"] > li::marker { font-size: 0.62em; }
.tw-cosolar--jianlan.resume-paper .paper-rich ul[data-list="diamond"] { list-style-type: "◆   "; }
.tw-cosolar--jianlan.resume-paper .paper-rich ul[data-list="diamond-open"] { list-style-type: "◇   "; }
.tw-cosolar--jianlan.resume-paper .paper-rich ul[data-list="diamond"] > li::marker,
.tw-cosolar--jianlan.resume-paper .paper-rich ul[data-list="diamond-open"] > li::marker { font-size: 0.62em; }
.tw-cosolar--jianlan.resume-paper .paper-rich ul[data-list="triangle"] { list-style-type: "▸   "; }
.tw-cosolar--jianlan.resume-paper .paper-rich ul[data-list="check"] { list-style-type: "✓   "; }
.tw-cosolar--jianlan.resume-paper .paper-rich ul[data-list="check"] > li::marker { font-size: 0.75em; }
.tw-cosolar--jianlan.resume-paper .paper-rich ol[data-list="decimal"] { list-style-type: decimal; }
.tw-cosolar--jianlan.resume-paper .paper-rich ol[data-list="cjk"] { list-style-type: miniwho-cjk; }
.tw-cosolar--jianlan.resume-paper .paper-rich ol[data-list="roman-upper"] { list-style-type: upper-roman; }
.tw-cosolar--jianlan.resume-paper .paper-rich ol[data-list="roman-lower"] { list-style-type: lower-roman; }
.tw-cosolar--jianlan.resume-paper .paper-rich ol[data-list="alpha-upper"] { list-style-type: upper-alpha; }
.tw-cosolar--jianlan.resume-paper .paper-rich ol[data-list="alpha-lower"] { list-style-type: lower-alpha; }
.tw-cosolar--jianlan.resume-paper .paper-rich ol[data-list="paren"] { padding-left: 1.2em; list-style: none; counter-reset: paren-item; }
.tw-cosolar--jianlan.resume-paper .paper-rich ol[data-list="paren"] > li { position: relative; counter-increment: paren-item; }
.tw-cosolar--jianlan.resume-paper .paper-rich ol[data-list="paren"] > li::before {
  content: "（" counter(paren-item) "）";
  position: absolute;
  right: calc(100% + 0.08em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-size: 0.62em;
  line-height: 1.7;
  white-space: nowrap;
}
.tw-cosolar--jianlan.resume-paper .paper-rich ol[data-list="paren-right"] { padding-left: 1.2em; list-style: none; counter-reset: paren-right-item; }
.tw-cosolar--jianlan.resume-paper .paper-rich ol[data-list="paren-right"] > li { position: relative; counter-increment: paren-right-item; }
.tw-cosolar--jianlan.resume-paper .paper-rich ol[data-list="paren-right"] > li::before {
  content: counter(paren-right-item) ")";
  position: absolute;
  right: calc(100% + 0.12em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
